with.script:
const regex = /^stable(\d+)$/
const baseRef = context.payload.pull_request.base.ref
const match = baseRef.match(regex)
if (match) {
  console.log('Setting server_major to ' + match[1]);
  core.exportVariable('server_major', match[1]);
  console.log('Setting current_day to ' + (new Date()).toISOString().substr(0, 10));
  core.exportVariable('current_day', (new Date()).toISOString().substr(0, 10));
}

steps.run:
set -e
# HTML sets DOCS_DISPLAY_VERSION via detect-versions and PDF via DOCS_RELEASE;
# the epub job needs it too so stable branches render their real version.
if [[ "${{ inputs.branch }}" =~ ^stable([0-9]+)$ ]]; then
  export DOCS_DISPLAY_VERSION="${BASH_REMATCH[1]}"
fi
cd ${{ matrix.manual.directory }}
make epub
ls -la ${{ matrix.manual.build_epub_path }}

set -e
cd ${{ matrix.manual.directory }}
make latexpdf
ls -la ${{ matrix.manual.build_pdf_path }}

php build/build-index.php ${{ steps.branch.outputs.branches }}
mv build/index.html /tmp/index.html
mv build/static/ /tmp/static/

with.script:
const triageLabels = ['0. Needs triage', '1. to develop', '2. developing', '3. to review', '4. to release']
const currentLabels = context.payload.pull_request.labels.map(l => l.name)
if (!triageLabels.some(l => currentLabels.includes(l))) {
  await github.rest.issues.addLabels({
    owner: context.repo.owner,
    repo: context.repo.repo,
    issue_number: context.payload.pull_request.number,
    labels: ['3. to review'],
  })
}

const triageLabels = ['0. Needs triage', '1. to develop', '2. developing', '3. to review', '4. to release']
const currentLabels = context.payload.issue.labels.map(l => l.name)
if (!triageLabels.some(l => currentLabels.includes(l))) {
  await github.rest.issues.addLabels({
    owner: context.repo.owner,
    repo: context.repo.repo,
    issue_number: context.payload.issue.number,
    labels: ['0. Needs triage'],
  })
}

const previewUrl = process.env.PREVIEW_URL || '';
const prNumber = context.payload.pull_request.number;
const MAX_LINKS = 20;
const COMMENT_MARKER = '<!-- netlify-preview-comment -->';
const updatedAt = new Date().toUTCString();

// Fetch all changed files in the PR (auto-paginated)
const allFiles = await github.paginate(github.rest.pulls.listFiles, {
  owner: context.repo.owner,
  repo: context.repo.repo,
  pull_number: prNumber,
  per_page: 100,
});

// Keep only RST files that live inside a built manual
const manuals = ['admin_manual/', 'developer_manual/', 'user_manual/'];
const rstFiles = allFiles
  .map(f => f.filename)
  .filter(f => manuals.some(m => f.startsWith(m)) && f.endsWith('.rst'));

// Build the changed-pages section
let changedSection = '';
if (previewUrl && rstFiles.length > 0) {
  const links = rstFiles.map(f => {
    // user_manual HTML is deployed under user_manual/en/; other manuals deploy as-is
    const htmlPath = f.startsWith('user_manual/')
      ? f.replace(/^user_manual\//, 'user_manual/en/').replace(/\.rst$/, '.html')
      : f.replace(/\.rst$/, '.html');
    return `- [${f}](${previewUrl}/${htmlPath})`;
  });
  const shown = links.slice(0, MAX_LINKS);
  const extra = links.length - shown.length;
  const extraLine = extra > 0
    ? `\n_…and ${extra} more. [View all changed files](https://github.com/${context.repo.owner}/${context.repo.repo}/pull/${prNumber}/files)_`
    : '';
  changedSection = [
    '',
    `<details>`,
    `<summary>📄 ${rstFiles.length} changed documentation ${rstFiles.length === 1 ? 'page' : 'pages'}</summary>`,
    '',
    shown.join('\n') + extraLine,
    '</details>',
  ].join('\n');
} else if (rstFiles.length === 0) {
  changedSection = '\n_No RST documentation pages changed in this PR._';
}

// Compose the full comment body
const previewLine = previewUrl
  ? `🔍 **[Open preview →](${previewUrl})**`
  : '⚠️ Preview deployment failed or was skipped.';
const body = [
  COMMENT_MARKER,
  '## 📖 Documentation Preview',
  '',
  previewLine,
  changedSection,
  '',
  `_Last updated: ${updatedAt}_`,
].join('\n');

// Update existing bot comment or create a new one
const comments = await github.paginate(github.rest.issues.listComments, {
  owner: context.repo.owner,
  repo: context.repo.repo,
  issue_number: prNumber,
  per_page: 100,
});
const existing = comments.find(c => c.body && c.body.includes(COMMENT_MARKER));
if (existing) {
  await github.rest.issues.updateComment({
    owner: context.repo.owner,
    repo: context.repo.repo,
    comment_id: existing.id,
    body,
  });
} else {
  await github.rest.issues.createComment({
    owner: context.repo.owner,
    repo: context.repo.repo,
    issue_number: prNumber,
    body,
  });
}
